warnings.filterwarnings('ignore')
tr=pd.read_csv('/work/alloy_pair_target_train.csv');pool=pd.read_csv('/work/alloy_pair_target_pool.csv');y=tr.target.values
X=tr.drop(columns=['target','Fe']);P=pool[X.columns];cat=['heat_treatment','route'];num=[c for c in X if c not in cat]
prep=ColumnTransformer([('num',StandardScaler(),num),('cat',OneHotEncoder(sparse_output=False),cat)])
cv=list(KFold(5,shuffle=True,random_state=42).split(X))
models={}
for a in [1,10,100]:models['ridge'+str(a)]=make_pipeline(prep,Ridge(alpha=a))
for a in [1,10,100,1000]:models['poly'+str(a)]=make_pipeline(prep,PolynomialFeatures(2,include_bias=False),StandardScaler(),Ridge(alpha=a))
for k in [3,4,5,7]:
 for a in [1,10]:
  sp=ColumnTransformer([('num',make_pipeline(SplineTransformer(n_knots=k,degree=3),StandardScaler()),num),('cat',OneHotEncoder(sparse_output=False),cat)])
  models[f'spline{k}_{a}']=make_pipeline(sp,Ridge(alpha=a))
for dep in [3,5,7]:models['cat'+str(dep)]=CatBoostRegressor(iterations=1600,depth=dep,learning_rate=.025,loss_function='RMSE',l2_leaf_reg=5,verbose=False,thread_count=2,cat_features=cat)
models['extra']=make_pipeline(prep,ExtraTreesRegressor(n_estimators=600,min_samples_leaf=2,n_jobs=2,random_state=42))
models['gbr']=make_pipeline(prep,GradientBoostingRegressor(n_estimators=600,max_depth=2,learning_rate=.03,loss='huber',random_state=42))
for C in [100,300,1000]:
 for gam in [.005,.02,.05]: models[f'svr{C}_{gam}']=make_pipeline(prep,SVR(C=C,gamma=gam,epsilon=15))
models['gp']=make_pipeline(prep,GaussianProcessRegressor(kernel=ConstantKernel(1,(.01,100))*RBF(np.ones(22),(0.1,100))+WhiteKernel(.05,(1e-4,1)),normalize_y=True,n_restarts_optimizer=1,random_state=42))
outputs={};oofs={}
for name,m in models.items():
 try:
