from sklearn.preprocessing import SplineTransformer
class FlexBump(BumpRegressor):
 def __init__(self,basis='quad',alpha=.01,starts=1,prior=0):self.basis=basis;self.alpha=alpha;self.starts=starts;self.prior=prior;self.bump_cols=(7,12,15)
 def makebase(self,Z,fit=False):
  if self.basis=='quad':return np.c_[np.ones(len(Z)),Z,Z[:,:16]**2]
  if self.basis=='cubic':return np.c_[np.ones(len(Z)),Z,Z[:,:16]**2,Z[:,:16]**3]
  if self.basis=='quartic':return np.c_[np.ones(len(Z)),Z,Z[:,:16]**2,Z[:,:16]**3,Z[:,:16]**4]
  if self.basis.startswith('spline'):
   if fit:self.sp=SplineTransformer(n_knots=int(self.basis[-1]),degree=3).fit(Z[:,:16])
   return np.c_[np.ones(len(Z)),self.sp.transform(Z[:,:16]),Z[:,16:]]
 def fit(self,Z,y):
  A=self.makebase(Z,True);z=Z[:,self.bump_cols];d=3
  std=prep.named_transformers_['num'].scale_[list(self.bump_cols)];mean=prep.named_transformers_['num'].mean_[list(self.bump_cols)]
  center=(np.array([.4,1135,38])-mean)/std;width=np.array([.08,25,10])/std
  reg=np.eye(A.shape[1]+1)*self.alpha;reg[0,0]=0;reg[-1,-1]=1e-7
  def solve(t):
   g=np.exp(-.5*(((z-t[:d])/np.exp(t[d:]))**2).sum(axis=1));B=np.c_[A,g];co=np.linalg.solve(B.T@B+reg,B.T@y)
   return co,B
  init=np.r_[center,np.log(width)];lo=np.r_[np.full(d,-2.5),np.full(d,np.log(.06))];hi=np.r_[np.full(d,2.5),np.full(d,np.log(2.0))]
  def fun(t):
   co,B=solve(t);r=np.r_[B@co-y,np.sqrt(np.diag(reg))*co]
   if self.prior>0:r=np.r_[r,(t-init)*self.prior]
   return r
  best=None;rng=np.random.RandomState(7)
  for i in range(self.starts):
   fit=least_squares(fun,np.clip(init+rng.normal(0,.2,len(init))*(i>0),lo+.001,hi-.001),bounds=(lo,hi),max_nfev=300)
   if best is None or np.sum(fit.fun**2)<np.sum(best.fun**2):best=fit
  self.theta=best.x;self.coef_,_=solve(self.theta);return self
 def predict(self,Z):
  z=Z[:,self.bump_cols];g=np.exp(-.5*(((z-self.theta[:3])/np.exp(self.theta[3:]))**2).sum(axis=1));return np.c_[self.makebase(Z),g]@self.coef_
