 outputs=pd.read_csv('/tmp/alloy_predictions.csv',index_col=0);oofs=pd.read_csv('/tmp/alloy_oofs.csv')
 specs=[('quad',a,0) for a in [.3,1,3]]+[('cubic',a,0) for a in [.01,.1,1]]+[('quartic',a,0) for a in [.1,1]]+[('spline3',a,0) for a in [.01,.1,1]]+[('spline4',a,0) for a in [.1,1]]+[('quad',.01,p) for p in [10,30,100]]
 for basis,a,prior in specs:
  m=FlexBump(basis,a,starts=1,prior=prior);oof=cross_val_predict(m,Z,y,cv=cv);m.fit(Z,y);p=m.predict(Q);name=f'flex_{basis}_{a}_{prior}';outputs[name]=p;oofs[name]=oof
  print(name,'RMSE',round(mean_squared_error(y,oof)**.5,2),'MAE',round(mean_absolute_error(y,oof),2),'TRAIN',round(mean_squared_error(y,m.predict(Z))**.5,2),m.description(),'TOP:',[(pool.candidate_id.iloc[i],round(p[i],1)) for i in np.argsort(abs(p-1051))[:12]],flush=True)
 outputs.to_csv('/tmp/alloy_predictions.csv');oofs.to_csv('/tmp/alloy_oofs.csv',index=False)

